import re,json,sys
from pathlib import Path
def parse(s):
 stack=[]
 for t in re.findall(r'\(|\)|[^\s()]+',s):
  if t=='(':stack.append([])
  elif t==')':
   x=stack.pop()
   if not stack:return x
   stack[-1].append(x)
  else:stack[-1].append(t)
def fmt(x):return '('+' '.join(map(fmt,x))+')' if isinstance(x,list) else x
name=sys.argv[1];d=json.load(open('/tmp/stationops-derivation/'+name+'.json'));b=d['batches'][1];rows={int(r[1]):r for r in map(parse,b['stores']['proof'])}
root='(LocalProblem shift-02 M01 old coolant-pump shift-02-M01)'
ids=[i for i,r in rows.items() if fmt(r[3][0])==root]
print('ROOT IDS',ids)
seen=set()
def walk(i,depth=0):
 r=rows[i];out=r[3];print(' '*depth, i, fmt(out) if out[0]=='CPU' else fmt(out[0])+' '+fmt(out[-1]), 'CHILDREN',r[-1])
 if i in seen:return
 seen.add(i)
 for c in r[-1]:walk(int(c),depth+2)
for i in ids:walk(i)

